export type GitLabIcon = keyof typeof paths;
export function gitlabIcon(name: GitLabIcon, size = 18): string {
  return '<svg class="gitlab-icon" width="' + size + '" height="' + size + '" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" focusable="false">' + paths[name] + '</svg>';
}
export function mountGitLabIcons(scope: ParentNode = document): void {
  scope.querySelectorAll<HTMLElement>('[data-icon]').forEach(element => {
    const name = element.dataset.icon as GitLabIcon;
    if (Object.hasOwn(paths, name)) element.innerHTML = gitlabIcon(name);
  });
}
